// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsConfigPath 是低库存阈值配置相对仓库根的位置；config/ 是本仓库放配置的地方。
const thresholdsConfigPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值从仓库根的 config/thresholds.json 读取，形如 {"shanghai": 20}。
// 文件不存在、读不出来或内容不是 JSON 对象时，一律按未配置处理，回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds := loadThresholds()
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析阈值配置；任何读取或解析失败都返回 nil。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsConfigPath)
	if err != nil {
		return nil
	}
	thresholds := map[string]int{}
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// withWorkingDir 在 dir 下执行 fn，结束后恢复原工作目录。
// LowStockThreshold 读的是相对工作目录的 config/thresholds.json，所以测试靠切目录来隔离配置。
func withWorkingDir(t *testing.T, dir string, fn func()) {
	t.Helper()
	previous, err := os.Getwd()
	if err != nil {
		t.Fatalf("获取工作目录失败: %v", err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatalf("切换到 %s 失败: %v", dir, err)
	}
	defer func() {
		if err := os.Chdir(previous); err != nil {
			t.Fatalf("恢复工作目录失败: %v", err)
		}
	}()
	fn()
}

// writeConfig 在 dir 下写 config/thresholds.json，内容为 content。
func writeConfig(t *testing.T, dir, content string) {
	t.Helper()
	configDir := filepath.Join(dir, "config")
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		t.Fatalf("创建 config 目录失败: %v", err)
	}
	if err := os.WriteFile(filepath.Join(configDir, "thresholds.json"), []byte(content), 0o644); err != nil {
		t.Fatalf("写配置失败: %v", err)
	}
}

func TestLowStockThresholdReadsConfiguredValue(t *testing.T) {
	dir := t.TempDir()
	writeConfig(t, dir, `{"shanghai": 20}`)
	withWorkingDir(t, dir, func() {
		if got := LowStockThreshold("shanghai"); got != 20 {
			t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
		}
		if got := LowStockThreshold("wuhan"); got != DefaultLowStockThreshold {
			t.Fatalf("未配置仓库 = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
		}
	})
}

func TestRepoConfigIsReadable(t *testing.T) {
	// go test 的工作目录是包目录，仓库根在上一级。
	withWorkingDir(t, "..", func() {
		if got := LowStockThreshold("shanghai"); got != 20 {
			t.Fatalf("读取仓库 config/thresholds.json 得到 %d, 期望 20", got)
		}
	})
}

func TestLowStockThresholdFallsBackWhenConfigMissing(t *testing.T) {
	withWorkingDir(t, t.TempDir(), func() {
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("配置缺失时 = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
		}
	})
}

func TestLowStockThresholdFallsBackWhenConfigMalformed(t *testing.T) {
	dir := t.TempDir()
	writeConfig(t, dir, `{"shanghai":`)
	withWorkingDir(t, dir, func() {
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("配置损坏时 = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
		}
	})
}

func TestLowStockThresholdFallsBackWhenConfigNotObject(t *testing.T) {
	dir := t.TempDir()
	writeConfig(t, dir, `[1, 2, 3]`)
	withWorkingDir(t, dir, func() {
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("配置不是 JSON 对象时 = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
		}
	})
}

